<template>
  <Error :heading="$t('errors_unexpected')" status_code="500" minimal>
    <p>{{ $t('errors_network_error_title') }}</p>
    <p>
      {{ $t('errors_network_error_body') }}
      <a class="cursor-pointer" :href="'tel:' + get_call_us_support_no()">{{
        $t('errors_call_us')
      }}</a>
      {{ $t('errors_urgent_matter_message') }}
      <a class="cursor-pointer" @click="help_center()">{{ $t('errors_help_center') }}</a>
    </p>
    <p>{{ $t('errors_thanks_message') }}</p>
  </Error>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import Error from 'src/pages/Errors/Error.vue';
import errorHelper from 'src/pages/Errors/helper';
import { healthCheckApiService } from 'src/services';

export default defineComponent({
  mixins: [errorHelper],
  components: { Error },
  data() {
    return {
      pingInterval: null as ReturnType<typeof setInterval> | null,
    };
  },
  beforeMount() {
    this.pingServer();
    this.pingInterval = setInterval(() => this.pingServer(), 1000);
  },
  beforeUnmount() {
    if (this.pingInterval) clearInterval(this.pingInterval);
  },
  methods: {
    hasHistory() {
      return window.history.length > 2;
    },
    async pingServer() {
      try {
        const hasRedirected = localStorage.getItem('hasRedirected');
        if (hasRedirected) {
          if (this.pingInterval) clearInterval(this.pingInterval);
          setTimeout(() => this.$router.push('/dashboard'), 1500);
          return;
        }
        const response = await healthCheckApiService.all();
        if (response.success === true) {
          localStorage.setItem('hasRedirected', 'true');
          if (this.pingInterval) clearInterval(this.pingInterval);
          this.hasHistory() ? this.$router.go(-1) : this.$router.push('/dashboard');
        }
      } catch (err: any) {
        logError(err);
      }
    },
  },
});
</script>
